import type { GameState } from '../shared/types';

/** Deliberately exclude client IDs, difficulty and any other API fields. */
export function completedPayload(state: GameState, duration: number): { home: number; away: number; duration: number } | null {
  return state.phase === 'finished'
    ? { home: state.score.home, away: state.score.away, duration }
    : null;
}

// Generated by local Ollama deepseek-r1:14b; reviewed and tested by coordinator.
export function controlledRoleLabel(state: GameState): string {
  const player = state.players.find(p => p.id === state.controlledId);
  if (!player) return "Player";
  if (player.role === "keeper") return "Goalkeeper";
  if (player.tacticalRole === "attacker") return "Attacker";
  if (player.tacticalRole === "midfielder") return "Midfielder";
  if (player.tacticalRole === "defender") return "Defender";
  return "Outfield player";
}
